"""Single source of truth for metric documentation. The API serves this to the Methodology page
and to every "How was this calculated?" popover, so docs cannot drift from the code."""

METRICS = [
 dict(id="clean_lap", name="Clean lap", status="implemented", needs_telemetry=False,
      definition="A lap that reflects underlying pace.",
      calculation="Excludes, in order: no time, lap 1, pit in/out laps, track status other than all-clear (SC/VSC/yellow/red), deleted times, laps >7% slower than the driver's own median.",
      data_used="Lap times, pit flags, track status, deleted flags.",
      limitations="Traffic and dirty air are not detectable from timing alone, so some laps marked clean are still slowed by traffic."),
 dict(id="fuel_corrected_time", name="Fuel-corrected lap time", status="implemented", needs_telemetry=False,
      definition="Lap time expressed as if run on the final lap's fuel load.",
      calculation="lap_time - 0.035 s x (total_laps - lap_number).",
      data_used="Lap times, lap number, race distance.",
      limitations="0.035 s/lap is an assumption. Real burn varies by circuit and car. Fuel load is not in public data."),
 dict(id="degradation", name="Tyre degradation rate", status="implemented", needs_telemetry=False,
      definition="Seconds lost per lap of tyre age within a stint.",
      calculation="OLS slope of fuel-corrected time on tyre age over clean laps in the stint, with its standard error. Stints with fewer than 5 clean laps return no value.",
      data_used="Clean laps, tyre age, compound, stint number.",
      limitations="Fuel and wear are collinear inside a stint, so the fuel constant is fixed first. Track evolution is not separated."),
 dict(id="teammate_delta", name="Teammate pace gap", status="implemented", needs_telemetry=False,
      definition="Median clean fuel-corrected pace of A minus B. Negative means A faster.",
      calculation="Difference of tyre-mix-adjusted driver effects (fuel-corrected clean laps, compound and tyre-age terms) with a 95% bootstrap interval from resampling laps within driver. If the interval spans zero, no clear difference is reported.",
      data_used="Clean laps for both teammates.",
      limitations="The dashboard and driver pages use the tyre-mix-adjusted version (fixed-effects model, same as the driver-vs-car model). Raw medians across different compounds are not comparable and are not used for gaps."),
 dict(id="consistency", name="Consistency score (0-100)", status="implemented", needs_telemetry=False,
      definition="How little a driver's lap and sector times vary, relative to the other drivers in the same session. 50 = field average.",
      calculation="Robust residual spread (1.4826 x MAD) of fuel-corrected laps after removing each stint's own tyre trend (70%) and of detrended sector times (30%); z-scored against the field, sign flipped, mapped through the normal CDF to 0-100.",
      data_used="Clean laps, sector times, stint numbers.",
      limitations="Relative to the session field only. Very noisy for a single race (about 16 points session-to-session in synthetic tests; real data likely worse), so use multi-race averages. Undetected traffic still adds noise. Needs at least 3 drivers with enough clean laps."),
 dict(id="driver_vs_car", name="Driver vs car decomposition", status="implemented", needs_telemetry=False,
      definition="A model estimate of how much of the gap between two drivers is associated with the car, the driver, and strategy/tyre/traffic circumstances.",
      calculation="Fixed-effects regression of fuel-corrected clean laps on driver, compound and compound-specific tyre age. Car part = difference of team mean driver effects; driver part = deviation from team mean; the remainder against the raw gap is circumstances. 95% intervals from bootstrap resampling of laps within driver.",
      data_used="Clean laps, compounds, tyre age, team membership.",
      limitations="Assumes teammates have equal cars and credits the shared team effect to the car. One race only. Treat as an estimate with the stated interval, never as measured fact."),
 dict(id="data_quality", name="Data completeness", status="implemented", needs_telemetry=False,
      definition="Share of a driver's recorded laps that survive the clean-lap filter, plus a list of what was excluded and why.",
      calculation="clean laps / laps present, with counts per exclusion reason.",
      data_used="Output of the clean-lap filter.",
      limitations="Cannot detect laps missing from the feed unless the expected lap count is known."),
 dict(id="corner_analysis", name="Corner entry / apex / exit deltas", status="planned", needs_telemetry=True,
      definition="Time gained or lost in braking, minimum speed and throttle phases per corner.",
      calculation="Distance-aligned telemetry comparison (Phase 3).", data_used="Speed, throttle, brake, distance.",
      limitations="Needs telemetry (2018 onward). Estimated deltas carry timing-alignment error."),
 dict(id="mixed_effects", name="Cross-season driver/car model", status="planned", needs_telemetry=False,
      definition="Separates driver and car using drivers who change teams.", calculation="Mixed-effects model (Phase 4).",
      data_used="Multi-season laps.", limitations="Only identifiable through driver moves; small samples."),
 dict(id="prediction", name="Predictions", status="planned", needs_telemetry=False,
      definition="Expected qualifying/race pace with intervals.", calculation="Transparent regression (Phase 5).",
      data_used="Historical pace.", limitations="Will always carry intervals; never presented as certain."),
]

BY_ID = {m["id"]: m for m in METRICS}
